package com.mfrp.plens.controller;import com.mfrp.plens.model.*;import com.mfrp.plens.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/submissions") @CrossOrigin(origins="http://localhost:4200") public class ProjectSubmissionController{private final ProjectSubmissionService service;public ProjectSubmissionController(ProjectSubmissionService s){service=s;}@GetMapping public List<ProjectSubmission> all(){return service.findAll();}@PostMapping public ProjectSubmission create(@RequestBody ProjectSubmission submission){return service.create(submission);}@PatchMapping("/{id}/decision") public ProjectSubmission decide(@PathVariable Long id,@RequestParam DecisionStatus status){return service.decide(id,status);}}
